<h2>Estimate signage area and vinyl quantity</h2><p class="lead">Calculate finished sign area and approximate roll length including a waste allowance.</p><div class="notice">This is a material-area estimator, not a nesting optimizer. Add realistic allowances for margins, overlaps, test cuts, defects, color matching and panel seams.</div><div class="form-grid"><div class="field"><label for="w">Sign width (m)</label><input id="w" type="number" value="1.2" min="0.001" step="any"></div><div class="field"><label for="h">Sign height (m)</label><input id="h" type="number" value="0.8" min="0.001" step="any"></div><div class="field"><label for="qty">Quantity</label><input id="qty" type="number" value="10" min="1" step="1"></div><div class="field"><label for="waste">Waste allowance (%)</label><input id="waste" type="number" value="12" min="0" step="any"></div><div class="field"><label for="roll">Vinyl roll width (m)</label><input id="roll" type="number" value="1.37" min="0.001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Finished sign area</span><strong id="area">—</strong></div><div class="metric"><span>Area incl. waste</span><strong id="buy">—</strong></div><div class="metric"><span>Approx. roll length</span><strong id="length">—</strong></div><div class="metric"><span>Area utilization</span><strong id="util">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('area').textContent='—';$('buy').textContent='—';$('length').textContent='—';$('util').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const w=num('w'),h=num('h'),q=num('qty'),wa=num('waste'),rw=num('roll');if(!(w>0&&h>0&&q>0&&wa>=0&&rw>0))throw 0;const a=w*h*q,b=a*(1+wa/100),len=b/rw,util=a/b*100;$('area').textContent=fmt(a,2)+' m²';$('buy').textContent=fmt(b,2)+' m²';$('length').textContent=fmt(len,2)+' m';$('util').textContent=fmt(util,1)+'%';$('note').textContent=w>rw?'Sign width exceeds the entered roll width. The area-based length does not account for panel seams or nesting; plan panels separately.':'Roll length is area ÷ roll width and does not optimize nesting, margins or panel orientation.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
